Q: IllegalSelectQueryException and InvalidDataAccessApiUsageException A: <p>write three annotation(@Query , @Transactional , @Modifying) while working with spring data jpa for dml query</p>
<pre><code>import java.util.List;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.transaction.annotation.Transactional;

import com.hcl.spring_boot_crud_operation_with_mysql.dto.Product;

public interface ProductRepository extends JpaRepository&lt;Product, Integer&gt; {

    List&lt;Product&gt; findByName(String name);

    @Query(&quot;UPDATE Product p SET p.price = :price WHERE p.id = :id&quot;)
    @Transactional
    @Modifying
    void updateProductPriceById(double price, int id);
}
</code></pre>

